import subprocess

# These addresses (0x2f4b20, 0x2f4c84) are in BSS/data region. They're NOT code.
# This means the tombstone unwinder likely failed for these frames on the SGen worker thread.
# The thread was in pthread_cond_wait and the unwinder produced garbage for parent frames.
# 
# However, for a complete report, let's check what the closest FUNCTION symbol is
# by looking at all 't' and 'T' type symbols
result = subprocess.run(['nm', '-n', '-C', '--defined-only', 'libmonosgen-2.0.so.debug'], capture_output=True, text=True)
funcs = []
for line in result.stdout.splitlines():
    parts = line.split(' ', 2)
    if len(parts) == 3 and parts[1] in ('t', 'T'):
        try:
            addr = int(parts[0], 16)
            funcs.append((addr, parts[2]))
        except ValueError:
            pass

funcs.sort()

# Actually let me also look for the 0x2c1a40 address (Finalizer thread)
# and also double-check the main thread addresses
all_targets = {
    'main #01': 0x222098,
    'main #02': 0x2241ac,
    'main #03': 0x1abc80,
    'main #04': 0x16de04,
    'SGen #02': 0x2f4b20,
    'SGen #03': 0x2f4c84,
    'Finalizer #02': 0x2c1a40,
}

for label, target in all_targets.items():
    best = None
    for addr, name in funcs:
        if addr <= target:
            best = (addr, name)
        else:
            break
    if best:
        offset = target - best[0]
        print(f'{label}: 0x{target:x} -> {best[1]}+0x{offset:x}')
    else:
        print(f'{label}: 0x{target:x} -> (no function symbol found)')
"", "description": "Resolve all frames to nearest functions"}
